#include <Arduino.h>
#include <Servo.h>

Servo motor;
unsigned long lastReport = 0;
bool firstReport = true;

void setup() {
  Serial.begin(9600);
  pinMode(3, INPUT);
  motor.attach(9);
  motor.write(digitalRead(3) == LOW ? 180 : 90);
}

void loop() {
  int angle = digitalRead(3) == LOW ? 180 : 90;
  motor.write(angle);
  unsigned long now = millis();
  if (firstReport || now - lastReport >= 100) {
    firstReport = false;
    lastReport = now;
    Serial.println(angle);
  }
}
